class Solution:
    def minEnergy(self, n: int, brightness: int, intervals: List[List[int]]) -> int:
        need = (brightness + 2) // 3
        end = max(e for _, e in intervals)
        on = bytearray(end + 1)
        for s, e in intervals:
            for t in range(s, e + 1):
                on[t] = 1
        return need * sum(on)

