class Solution {
public:
    long long minEnergy(int n, int brightness, vector<vector<int>>& intervals) {
        long long need = ((long long)brightness + 2) / 3;
        int end = 0;
        for (auto& iv : intervals) end = max(end, iv[1]);
        vector<char> on(end + 1, 0);
        for (auto& iv : intervals)
            for (int t = iv[0]; t <= iv[1]; t++) on[t] = 1;
        long long cnt = 0;
        for (char c : on) cnt += c;
        return need * cnt;
    }
};

