class Solution {
    public long minEnergy(int n, int brightness, int[][] intervals) {
        long need = ((long) brightness + 2) / 3;
        int end = 0;
        for (int[] iv : intervals) end = Math.max(end, iv[1]);
        boolean[] on = new boolean[end + 1];
        for (int[] iv : intervals)
            for (int t = iv[0]; t <= iv[1]; t++) on[t] = true;
        long cnt = 0;
        for (boolean b : on) if (b) cnt++;
        return need * cnt;
    }
}

