class Solution:
    def minEnergy(self, n: int, brightness: int, intervals: List[List[int]]) -> int:
        need = (brightness + 2) // 3
        intervals.sort()
        total = 0
        cs, ce = intervals[0]
        for s, e in intervals[1:]:
            if s <= ce:
                ce = max(ce, e)
            else:
                total += ce - cs + 1
                cs, ce = s, e
        total += ce - cs + 1
        return need * total

