class Solution {
public:
    long long minEnergy(int n, int brightness, vector<vector<int>>& intervals) {
        long long need = ((long long)brightness + 2) / 3;
        sort(intervals.begin(), intervals.end());
        long long total = 0;
        long long cs = intervals[0][0], ce = intervals[0][1];
        for (int i = 1; i < (int)intervals.size(); i++) {
            long long s = intervals[i][0], e = intervals[i][1];
            if (s <= ce) ce = max(ce, e);
            else { total += ce - cs + 1; cs = s; ce = e; }
        }
        total += ce - cs + 1;
        return need * total;
    }
};

